#define iterations 17
#define formuparam 0.53

#define volsteps 20
#define stepsize 0.1

#define zoom   0.800
#define tile   0.850
#define speed  0.000 

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850

vec3 getColor(vec2 p) {
    // Map to screen and get radius
    p = 2. * (2. * p - iResolution.xy) / iResolution.y;
    vec2 r = .1 + 5. / iResolution.xy;

    // Invert in ellipse
    float fac = 0.1;
    vec2 rr = r * r, pp = p * p;
    if (rr.y * pp.x + rr.x * pp.y > rr.x * rr.y) {
        p *= rr.x * rr.y / dot(pp, rr.yx);
        fac = 1.1;
    }

    // Get color
    return texture(iChannel0, p + .1 * iTime).xyz * fac;
}

void mainVR( out vec4 fragColor, in vec2 fragCoord, in vec3 ro, in vec3 rd )
{
	//get coords and direction
	vec3 dir=rd;
	vec3 from=ro;

	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v=vec3(0.);
	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam; // the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v+=fade;
		v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust
	fragColor = vec4(v*.03,1.);	
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;
	uv.y*=iResolution.y/iResolution.x;
	vec3 dir=vec3(uv*zoom,1.);
	vec2 cPos = -1.0 + 2.0 * fragCoord.xy / iResolution.xy;

    // distance of current pixel from center
	float cLength = length(cPos);


vec2 p =fragCoord;


	 vec3 col = getColor(p);
    col += getColor(p + vec2(.5, 0.));
    col += getColor(p + vec2(-.5, 0.));
    col += getColor(p + vec2(0., .5));
    col += getColor(p + vec2(0., -.5));

	vec3 from=vec3(1.,.5,0.5)+col;
	from.xy=(cPos/cLength)*cos(cLength*12.0-iTime*3.0) * 0.03;

	mainVR(fragColor, fragCoord, from, dir);	
}
